    Var i("i"), j("j"), k("k");

    // Funcs to initialize each buffer
    Func init_A("init_A"), init_B("init_B"), init_C("init_C");

    // Use Expr() wrappers for scalar constants to avoid ambiguous casts.
    Expr ni_e = Expr(ni);
    Expr nj_e = Expr(nj);
    Expr nk_e = Expr(nk);

    // C[i][j] = ((i*j+1) % ni) / ni;
    // Buffer layout: C(j, i)
    init_C(j, i) = cast<num_t>(((i * j + 1) % ni_e)) / ni_e;

    // A[i][j] = (i*(j+1) % nk) / nk;
    // Buffer layout: A(k, i) where k is the "j" from the C code
    init_A(k, i) = cast<num_t>((i * (k + 1) % nk_e)) / nk_e;

    // B[i][j] = (i*(j+2) % nj) / nj;
    // Buffer layout: B(j, k) where i in C code is our k, and j is j
    init_B(j, k) = cast<num_t>((k * (j + 2) % nj_e)) / nj_e;

    // Simple CPU schedule for the initializers.
    // These run only once, but we still give them a cache-friendly layout.
    Target target = get_host_target();
    int vec_width = Halide::natural_vector_size(target, type_of<num_t>());
    if (vec_width <= 0) vec_width = 1;

    init_C
        .compute_root()
        .reorder(j, i)     // j (C's column) is innermost => stride-1 access
        .parallel(i)       // parallelize over rows
        .vectorize(j, vec_width);

    init_A
        .compute_root()
        .reorder(k, i)     // k (A's column) innermost
        .parallel(i)
        .vectorize(k, vec_width);

    init_B
        .compute_root()
        .reorder(j, k)     // j (B's column) innermost
        .parallel(k)
        .vectorize(j, vec_width);

    // Realize initialization into the provided buffers
    init_C.realize(C);
    init_A.realize(A);
    init_B.realize(B);
