    //   for (k = 0; k < nk; k++) {
    //      for (j = 0; j < nj; j++)
    //         C[i][j] += alpha * A[i][k] * B[k][j];
    //   }
    // }
    //
    // This is equivalent to:
    //   C[i][j] = beta * C[i][j] +
    //             sum_{k=0..nk-1}(alpha * A[i][k] * B[k][j]);
    //
    // Mapping to Halide coordinates:
    //   C(i,j) => C_param(j, i)
    //   A(i,k) => A_param(k, i)
    //   B(k,j) => B_param(j, k)
    //
    // We'll implement C := beta*C + alpha*A*B using a reduction.
    Func gemm("gemm");

    Expr alpha_e = Expr(alpha);
    Expr beta_e  = Expr(beta);

    // Pure definition: initialize each output element with beta * C
    // gemm(j, i) corresponds to C[i][j] in the original code.
    gemm(j, i) = beta_e * C_param(j, i);

    // Update definition: accumulate alpha * A * B over k
    gemm(j, i) += alpha_e * A_param(k, i) * B_param(j, k);

    // ------------------------------------------------------------------
    // Optimized schedule for GEMM
    // ------------------------------------------------------------------
    //
    // Layout recap:
    //   - C(j,i): j is contiguous in memory.
    //   - B(j,k): j is contiguous; good candidate for vectorization in j.
    //   - A(k,i): k is contiguous, but for fixed (i,k) we can reuse the
    //             same scalar across all j in a tile.
    //
    // We:
    //   * compute gemm at root,
    //   * tile the (j,i) space to improve cache locality,
    //   * parallelize across tiles of i,
    //   * vectorize across j inside each tile,
    //   * order the reduction as (i_tile, j_tile, k, i_in_tile, j_in_tile)
    //     so that B(j,k) is accessed contiguously and A(k,i) is reused.
    //

    Target target = get_host_target();
    int vec_width = Halide::natural_vector_size(target, type_of<num_t>());
    if (vec_width <= 0) vec_width = 1;

    Var jo("jo"), ji("ji"), io("io"), ii("ii");

    // Compute the full GEMM at root in tiled fashion.
    gemm.compute_root();

    // Tile the (j,i) space and schedule the pure definition.
    gemm
        .tile(j, i, jo, io, ji, ii, TILE_J, TILE_I)
        // Within each tile, j_in (ji) is contiguous -> good for SIMD.
        .vectorize(ji, vec_width)
        // Parallelize across tiles of the i dimension (rows of C).
        .parallel(io);

    // Apply a matching tiled schedule to the update (reduction) step.
    // After tiling, the update has loops over {jo, io, ji, ii} and RDom k.
    // We reorder to get: io (outer, parallel), jo, k, ii, ji (innermost).
    gemm.update()
        .tile(j, i, jo, io, ji, ii, TILE_J, TILE_I)
        .reorder(ji, ii, k, jo, io)  // arguments from innermost to outermost
        .vectorize(ji, vec_width)
        .parallel(io);

    // Bind the ImageParams to the concrete Buffers
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Compile the kernel to machine code (JIT) for the host target
    gemm.compile_jit(target);

