    *beta  = (num_t)1.2;

    Var i("i"), j("j"), k("k");
    Func init_A("init_A"), init_B("init_B"), init_C("init_C");

    // Wrap scalar ints as Exprs once; avoids awkward casts.
    Expr ni_e = Expr(ni);
    Expr nj_e = Expr(nj);
    Expr nk_e = Expr(nk);

    // C[i][j] = ((i*j+1) % ni) / ni;
