    // Buffer layout: B(j, k) where i in C code is our k, and j is j
    init_B(j, k) = cast<num_t>((k * (j + 2) % nj)) / nj_e;

    // --- Schedule for initialization stages --------------------------------
    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    // C: rows (i) in parallel, columns (j) vectorized
    init_C
        .parallel(i)
        .vectorize(j, vec);

    // A: rows (i) in parallel, reduction dimension (k) vectorized
    init_A
        .parallel(i)
        .vectorize(k, vec);

    // B: rows over k, columns (j) vectorized
    init_B
        .parallel(k)
        .vectorize(j, vec);

