    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> A(nk, ni);

    // ImageParams to represent the input/output images for the Halide pipeline.
    // They share the same logical layout as the Buffers above.
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data as in the original C code.
    init_array(ni, nj, nk, &alpha, &beta, C, A, B);

    // Define Vars
    Var i("i"), j("j");

    // Reduction domain over k = 0..nk-1 (the shared dimension of A and B)
    RDom k(0, nk, "k");

    // Main GEMM computation:
    //
    // Original C kernel:
    //
    // for (i = 0; i < ni; i++) {
    //   for (j = 0; j < nj; j++)
    //       C[i][j] *= beta;
    //   for (k = 0; k < nk; k++) {
    //      for (j = 0; j < nj; j++)
    //         C[i][j] += alpha * A[i][k] * B[k][j];
    //   }
    // }
    //
    // This is equivalent to:
    //   C[i][j] = beta * C[i][j] +
    //             sum_{k=0..nk-1}(alpha * A[i][k] * B[k][j]);
    //
    // Mapping to Halide coordinates:
    //   C(i,j) => C_param(j, i)   (C is (nj x ni) buffer)
    //   A(i,k) => A_param(k, i)   (A is (nk x ni) buffer)
    //   B(k,j) => B_param(j, k)   (B is (nj x nk) buffer)
    //
    // We implement C := beta*C + alpha*A*B using a reduction.
    Func gemm("gemm");

    // Pure definition: initialize each output element with beta * C
    gemm(j, i) = Expr(beta) * C_param(j, i);

    // Update definition: accumulate alpha * A * B over k
    gemm(j, i) += Expr(alpha) * A_param(k, i) * B_param(j, k);

    // ----------------------- Schedule for GEMM -------------------------------
    //
    // Key goals:
    //   * Make j (x dimension) contiguous & vectorized.
    //   * Traverse B row-wise inside the k-loop: for each (i,k), walk B(k,:)
    //     linearly in memory.
    //   * Split i into tiles to get good parallel work granularity.
    //   * Parallelize across i-tiles; each thread owns a band of rows of C.
    //
    // Memory layouts:
    //   - A(k, i): contiguous in k for fixed i.
    //   - B(j, k): contiguous in j for fixed k.
    //   - C(j, i): contiguous in j for fixed i.
    //
    // We want loops like:
    //   for (io, ii, k, jo, ji) where:
    //       i = io*TILE_I + ii
    //       j = jo*VEC + ji
    //   So for fixed (io, ii, k) we sweep j (jo,ji) innermost:
    //     * B(j,k) is read row-wise
    //     * C(j,i) is written row-wise
    //     * A(k,i) is a single scalar reused across all j at that (i,k)

    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    Var io("io"), ii("ii"), jo("jo"), ji("ji");

    // Split i into tiles and j into vector-width chunks.
    gemm
        .split(i, io, ii, TILE_I)   // i = io * TILE_I + ii
        .split(j, jo, ji, vec)      // j = jo * vec    + ji
        .reorder(ji, jo, ii, io);   // inner: ji, then jo, then ii, outer: io

    // Pure definition: scale C by beta.
    gemm
        .parallel(io)               // distribute tiles of rows across threads
        .vectorize(ji);             // vectorize across contiguous j (x) dimension

    // Update (reduction) definition:
    // Reorder to (i-tile, i-in-tile, k, j-outer, j-inner)
    // so that for fixed (i, k) we sweep over j contiguously.
    gemm.update()
        .reorder(ji, jo, k, ii, io) // loops: for io, ii, k, jo, ji
        .parallel(io)
        .vectorize(ji);

    // Bind the ImageParams to the concrete Buffers.
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Compile the kernel to machine code (JIT) for the current host.
    gemm.compile_jit(target);

    // Measure execution time of the GEMM kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write the result into C
    gemm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the resulting C, similar to PolyBench's print_array.
    using namespace std::string_literals;
