    //   B(k,j) => B_param(j, k)
    //
    // We'll implement C := beta*C + alpha*A*B using a reduction.
    Func gemm("gemm");

    // Pure definition: initialize each output element with beta * C
    gemm(j, i) = Expr(beta) * C_param(j, i);

    // Update definition: accumulate alpha * A * B over k
    gemm(j, i) += Expr(alpha) * A_param(k, i) * B_param(j, k);

    // --------------------------
    // Performance-oriented schedule
    // --------------------------
    //
    // Goals:
    //   * Make j (columns) contiguous and vectorized (dimension 0 is
    //     contiguous in memory for all Buffers).
    //   * Tile i and j to improve cache locality over C, A, and B.
    //   * Parallelize across tiles to exploit many CPU cores.
    //   * Keep the reduction over k innermost for good A- and B-access
    //     patterns:
    //       - A_param(k, i): contiguous in k
    //       - B_param(j, k): contiguous in j
    //
    // We use modest tile sizes as tunable constants; they can be
    // adjusted for a specific machine/cache without changing
    // correctness.
    const int tile_i = 64;   // tile size in the i (row) dimension
    const int tile_j = 128;  // tile size in the j (column) dimension

    // Choose a reasonable vector width for the element type on this host.
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        // Fallback: a conservative vector width if the target can't
        // report something sensible (or for scalar types without
        // vector support).
        vec_width = 4;
    }

    // Tile the (j, i) space. After tiling, the pure vars are:
    //   tile (fused jo, io) : tile index (outermost, parallelized)
    //   ji : column inside a tile (innermost, vectorized)
    //   ii : row   inside a tile
    //
    // Memory layout:
    //   * C(j, i): j is dimension 0 => contiguous in memory.
    //   * B(j, k): j is dimension 0 => contiguous, good for vectorization.
    //   * A(k, i): k is dimension 0 => contiguous, good for scanning k.
    //
    // Fusing jo and io gives many independent tiles to distribute
    // across threads while staying within a single parallel loop.
    gemm
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .fuse(jo, io, tile)
        .reorder(ji, ii, tile)   // ji innermost, then ii, then tile outermost
        .vectorize(ji, vec_width)
        .parallel(tile);

    // Schedule the reduction update to match the tiling of the pure
    // definition. We want the update loops to iterate tiles in the
    // same way, then loop over rows (ii), then over k, and finally
    // vectorize across ji (columns).
    //
    // Loop order (from outermost to innermost):
    //   tile -> ii -> k -> ji
    //
    // This gives:
    //   * For A_param(k, i): k is innermost w.r.t. ii, so we stream
    //     contiguous A values along k for each row ii.
    //   * For B_param(j, k): ji is innermost, so we do vectorized,
    //     contiguous loads along j for each (k, ii).
    gemm.update()
        .reorder(ji, k, ii, tile)   // ji innermost
        .vectorize(ji, vec_width);

    // Compile the kernel to machine code (JIT) with the chosen target
    gemm.compile_jit(target);

    // Measure execution time of the GEMM kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write the result into C
    gemm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the resulting C, similar to PolyBench's print_array.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nj; jj++) {
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout
